<?php
namespace App\Services;
use App\Models\{CreditNote,Product,Sale,SaleReturn,SaleReturnItem};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class SaleReturnService
{
 public function post(Sale $sale,array $data,$user):SaleReturn{return DB::transaction(function()use($sale,$data,$user){$sale=Sale::with('items.product')->where('company_id',$user->company_id)->lockForUpdate()->findOrFail($sale->id);$prepared=[];$total=$costTotal='0';foreach($sale->items as $item){$qty=(string)($data['items'][$item->id]['quantity']??0);if(bccomp($qty,'0',4)<=0)continue;$returned=(string)SaleReturnItem::where('sale_item_id',$item->id)->sum('quantity');$remaining=bcsub((string)$item->quantity,$returned,4);if(bccomp($qty,$remaining,4)>0)throw ValidationException::withMessages(['items'=>"{$item->product->name}: return quantity exceeds {$remaining} remaining."]);$line=bcmul($qty,(string)$item->unit_price,2);$cost=bcmul($qty,(string)$item->unit_cost,2);$condition=$data['items'][$item->id]['condition']??'resalable';$total=bcadd($total,$line,2);$costTotal=bcadd($costTotal,$cost,2);$prepared[]=compact('item','qty','line','cost','condition');}if(!$prepared)throw ValidationException::withMessages(['items'=>'Enter at least one return quantity.']);$number=app(DocumentNumberService::class)->next($user->company_id,'sale_return','SR');$return=SaleReturn::create(['company_id'=>$user->company_id,'sale_id'=>$sale->id,'customer_id'=>$sale->customer_id,'created_by'=>$user->id,'document_number'=>$number,'return_date'=>now(),'return_type'=>count($prepared)===$sale->items->count()?'full':'partial','settlement_type'=>$data['settlement_type'],'status'=>'posted','total_amount'=>$total,'cost_total'=>$costTotal,'reason'=>$data['reason'],'posted_at'=>now()]);$location=DB::table('stock_locations')->where('company_id',$user->company_id)->where('is_default',1)->value('id');$stockCost='0';foreach($prepared as $x){$return->items()->create(['sale_item_id'=>$x['item']->id,'product_id'=>$x['item']->product_id,'quantity'=>$x['qty'],'unit_price'=>$x['item']->unit_price,'unit_cost'=>$x['item']->unit_cost,'line_total'=>$x['line'],'cost_total'=>$x['cost'],'condition'=>$x['condition']]);if($x['condition']==='resalable'){$p=Product::lockForUpdate()->findOrFail($x['item']->product_id);$beforeValue=bcmul((string)$p->current_quantity,(string)$p->average_cost,8);$afterQty=bcadd((string)$p->current_quantity,$x['qty'],4);$afterCost=bcdiv(bcadd($beforeValue,bcmul($x['qty'],(string)$x['item']->unit_cost,8),8),$afterQty,4);$p->update(['current_quantity'=>$afterQty,'average_cost'=>$afterCost]);$stockCost=bcadd($stockCost,$x['cost'],2);DB::table('stock_movements')->insert(['company_id'=>$user->company_id,'product_id'=>$p->id,'stock_location_id'=>$location,'created_by'=>$user->id,'movement_at'=>now(),'movement_type'=>'sales_return','reference_type'=>SaleReturn::class,'reference_id'=>$return->id,'reference_number'=>$number,'quantity_in'=>$x['qty'],'quantity_out'=>0,'balance_quantity'=>$afterQty,'unit_cost'=>$x['item']->unit_cost,'stock_value'=>bcmul($afterQty,$afterCost,2),'notes'=>$data['reason'],'created_at'=>now(),'updated_at'=>now()]);}}
 if($data['settlement_type']==='credit_note')CreditNote::create(['company_id'=>$user->company_id,'customer_id'=>$sale->customer_id,'sale_return_id'=>$return->id,'created_by'=>$user->id,'document_number'=>app(DocumentNumberService::class)->next($user->company_id,'credit_note','CN'),'note_date'=>now(),'amount'=>$total,'status'=>'available','reason'=>$data['reason']]);$revenue=$sale->channel==='wholesale'?'4200':'4100';$settlement=$data['settlement_type']==='cash_refund'?'1110':'1130';$journal=[['account_code'=>$revenue,'debit'=>$total],['account_code'=>$settlement,'credit'=>$total,'customer_id'=>$data['settlement_type']==='credit_note'?$sale->customer_id:null]];if(bccomp($stockCost,'0',2)>0){$journal[]=['account_code'=>'1140','debit'=>$stockCost];$journal[]=['account_code'=>'5100','credit'=>$stockCost];}app(JournalPostingService::class)->post($user->company_id,now()->toDateString(),SaleReturn::class,$return->id,$number,"Sales return {$number}",$journal,$user->id);if($data['settlement_type']==='credit_note'){$newBalance=max(0,(float)$sale->balance_amount-(float)$total);$sale->update(['balance_amount'=>$newBalance,'payment_status'=>$newBalance<=0?'paid':'partially_paid']);}return $return;});}
}
